#include "kstationControllerAdcEventRuntime.h"
#include "h8s/h8s.hpp"
#include <array>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <memory>
#include <vector>
struct Ref:H8SEmulator{void history(){lastread=lastwrite=-1;}};
struct Event{uint64_t at;uint32_t addr;uint8_t value;bool write;};
static bool mapped(uint32_t a){return (a>=0xc1cc&&a<0xc3d2)||(a>=0xc8ae&&a<0xc8b2);}
struct RBus:H8SDevice{Ref&c;std::array<Event,8>e{};unsigned n=0;explicit RBus(Ref&v):c(v){}uint8_t read(uint32_t a)override{auto v=c.memory[a];e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={c.cycles,a,v,true};c.memory[a]=v;}};
struct NBus:kstation::ControllerResourceBus{std::array<Event,8>e{};unsigned n=0;bool enabled=false;bool mapped(uint32_t a)const override{return ::mapped(a);}uint8_t read(uint32_t a)override{auto v=state_->memory[a];if(enabled)e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(enabled)e[n++]={state_->cycles,a,v,true};state_->memory[a]=v;}};
int main(int argc,char**argv){if(argc!=2)return 77;bool boot=false;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);if(!boot)d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0xc1cc,0x206);c->memmap(&x,0xc8ae,4);d->attachBus(&y);kstation::ControllerInterruptRuntime irq;kstation::ControllerAdcEventRuntime rt;if(!irq.bindVerifiedFirmware(*d,rom.data(),rom.size())||!rt.bindVerifiedFirmware(*d,rom.data(),rom.size()))return 2;y.enabled=true;uint64_t graphs=0,phases=0,events=0,shorts=0;for(unsigned scenario=0;scenario<64;++scenario)for(unsigned flags=0;flags<256;++flags){rt.reset();irq.reset();irq.setMask(flags&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);auto put=[&](uint32_t a,uint8_t v){c->memory[a]=d->memory[a]=v;};for(unsigned i=0;i<0x206;++i)put(0xc1cc+i,uint8_t(i*31+flags));for(unsigned i=0;i<4;++i)put(0xc8ae + i,uint8_t(flags*17+scenario*7+i*73));unsigned kind=scenario%3;uint8_t channel=scenario%5==0?0x1c:scenario%5==1?0x1d:uint8_t(scenario*13);uint8_t value=uint8_t(flags*7+scenario);uint16_t tail=uint16_t((flags*3)&0x1ff);put(0xc1ce,tail>>8);put(0xc1cf,tail);uint16_t head=scenario%4?uint16_t((tail+2)&0x1fe):tail;put(0xc1cc,head>>8);put(0xc1cd,head);put(0xc1d0+tail,value);put(0xc1d1+tail,channel);uint32_t source=(scenario&1)?0xc8ae:0xc8b0;uint16_t bias=uint16_t(flags*257);uint32_t entry=kind==0?0x5ee:kind==1?0x1fac:0x1fee;c->pc=c->makepc(entry);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->reg8(14)=int8_t(channel);c->reg8(6)=int8_t(value);c->reg32(2)=int32_t(source);c->reg16(3)=int16_t(bias);c->ccr=uint8_t(flags);c->pending_irqs=d->pendingIrqs=((flags&0x81)==0x81)?1:0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;c->cycles=d->cycles=100000;c->history();d->lastRead=d->lastWrite=-1;if(!rt.start(static_cast<kstation::ControllerAdcEventRuntime::Kind>(kind),channel,value,source,bias))return 3;for(unsigned k=0;rt.active();++k){if(k>1000)return 4;auto at=uint32_t(c->getPC());x.n=y.n=0;auto cost=rt.nextClocks(*d,irq);if(!cost){std::fprintf(stderr,"cost pc=%x scenario=%u flags=%u\n",at,scenario,flags);return 5;}if(phases%31==0){auto before=d->cycles;for(unsigned b=0;b<cost;++b){auto r=rt.advanceBefore(*d,irq,b);if(r.clocks||d->cycles!=before||y.n)return 6;++shorts;}}c->step();auto r=rt.advanceBefore(*d,irq,cost);if(!r.clocks||c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase pc=%x scenario=%u flags=%u clocks=%llu/%llu io=%u/%u\n",at,scenario,flags,c->cycles,d->cycles,x.n,y.n);return 7;}for(unsigned i=0;i<x.n;++i)if(x.e[i].at!=y.e[i].at||x.e[i].addr!=y.e[i].addr||x.e[i].value!=y.e[i].value||x.e[i].write!=y.e[i].write){std::fprintf(stderr,"event pc=%x scenario=%u addr=%x/%x value=%x/%x time=%llu/%llu\n",at,scenario,x.e[i].addr,y.e[i].addr,x.e[i].value,y.e[i].value,x.e[i].at,y.e[i].at);return 8;}events+=x.n;++phases;}if(c->getPC()!=0x7000)return 9;if(kind==0&&rt.event()!=uint32_t(c->reg32(6)))return 10;if(kind!=0&&rt.value()!=uint8_t(c->reg8(6)))return 11;if(std::memcmp(c->memory+0xc1cc,d->memory+0xc1cc,0x206))return 12;++graphs;}std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu}\n",(unsigned long long)graphs,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts);}
